const pname=n=>pitches[n%12].padEnd(2,'-')+(Math.floor(n/12)-1);
const parseNotes=s=>String(s).trim().toUpperCase().split(/[ ,+]+/).filter(Boolean).map(x=>{if(/^\d+$/.test(x))return int(+x,0,127,60);const m=x.match(/^([A-G])([#B-]?)(-?\d)$/);if(!m)return null;let p={C:0,D:2,E:4,F:5,G:7,A:9,B:11}[m[1]]+(m[2]==='#'?1:m[2]==='B'?-1:0);return Math.max(0,Math.min(127,(+m[3]+1)*12+p));});
