const defaultTrackName=i=>i<6?tx(LEGACY_TRACKS[i]):i<8?tx('Vrij {0}',i+1):tx('Spoor {0}',i+1);
const makePattern=(id,name='',length=16,count=8)=>({id,name,length,swing:0,channels:Array.from({length:count},()=>[])});
