 const time=num(info?.time,0,1e12,ctx.currentTime),dur=num(info?.stepDur,.001,60,.125),factor=S.rowsPerBeat/4;const swing=num(info?.swing,0,.95,0),span=dur*(step%2?1-swing:1+swing);lastDur=factor===.5?dur*2:span/factor;lastBpm=num(info?.bpm,10,999,120);const elapsed=absolute-origin;const count=factor>=1?factor:elapsed%Math.round(1/factor)===0?1:0;if(!count)return;
