 function rowSwing(e,track,raw){const loc=locate(e.row,track),tr=S.tracks[track],note=raw-(loc?.shift||0);return Math.min(.5,(loc?.p?.swing||0)+(tr?.swing||0)+(tr?.lanes?.[note]||0));}
